sys_script_include.script:
var bfd_CaseUtils = Class.create();
bfd_CaseUtils.prototype = {
    CASE_TABLE: 'x_1755386_safetr_0_bfd_fraud_dispute_case',
    TASK_TABLE: 'x_1755386_safetr_0_bfd_case_task',
    MANDATORY_TYPES: 'identity_verification,transaction_review,approval',
    HIGH_VALUE_THRESHOLD: 500,

    initialize: function () {},

    // ---------------------------------------------------------------- helpers
    _str: function (gr, field) {
        if (!gr || !field) return '';
        var v = gr.getValue(field);
        return v === null || v === undefined ? '' : ('' + v);
    },
    _num: function (gr, field) {
        var v = this._str(gr, field);
        if (v === '') return 0;
        var n = parseFloat(v);
        return isNaN(n) ? 0 : n;
    },

    // ------------------------------------------------------ mandatoryTasksComplete
    // true only when the case has NO mandatory task still open / work_in_progress.
    mandatoryTasksComplete: function (caseGr) {
        if (!caseGr) return false;
        var caseId = caseGr.getUniqueValue();
        if (!caseId) return true;
        var gr = new GlideRecord(this.TASK_TABLE);
        gr.addQuery('case', caseId);
        gr.addQuery('task_type', 'IN', this.MANDATORY_TYPES);
        gr.addQuery('status', 'IN', 'open,work_in_progress');
        gr.setLimit(1);
        gr.query();
        return !gr.hasNext();
    },

    // --------------------------------------------------------- stampResolutionDates
    stampResolutionDates: function (caseGr) {
        if (!caseGr) return false;
        var status = this._str(caseGr, 'case_status');
        if (status !== 'resolved' && status !== 'closed') return false;
        if (this._str(caseGr, 'actual_resolution_date') === '') {
            caseGr.setValue('actual_resolution_date', new GlideDateTime().getValue());
            return true;
        }
        return false;
    },

    // ----------------------------------------------------- highValueApprovalRequired
    highValueApprovalRequired: function (caseGr, threshold) {
        if (!caseGr) return false;
        var limit = parseFloat(threshold);
        if (isNaN(limit)) limit = this.HIGH_VALUE_THRESHOLD;

        if (this._num(caseGr, 'provisional_credit_amount') > limit) return true;
        if (this._str(caseGr, 'card_action') === 'permanent_block') return true;
        if (this._num(caseGr, 'recovery_amount') > limit) return true; // high-value reversal/recovery
        return false;
    },

    type: 'bfd_CaseUtils'
};
